import pandas as pd


# ==========================================================
# PRODUCT KPI ENGINE
# ==========================================================

def total_products(df):
    """Return the number of unique products."""

    return df["Product ID"].nunique()


def total_product_revenue(df):
    """Return total revenue generated by products."""

    return df["Revenue"].sum()


def total_product_profit(df):
    """Return total profit generated by products."""

    return df["Profit"].sum()


def average_product_revenue(df):
    """Return average revenue per unique product."""

    products = df["Product ID"].nunique()

    if products == 0:
        return 0

    return df["Revenue"].sum() / products


def average_product_profit(df):
    """Return average profit per unique product."""

    products = df["Product ID"].nunique()

    if products == 0:
        return 0

    return df["Profit"].sum() / products


def product_profit_margin(df):
    """Return overall product profit margin."""

    revenue = df["Revenue"].sum()

    if revenue == 0:
        return 0

    return (
        df["Profit"].sum()
        / revenue
        * 100
    )


def total_units_sold(df):
    """Return total quantity of products sold."""

    return df["Quantity"].sum()


# ==========================================================
# PRODUCT PERFORMANCE
# ==========================================================

def top_products_by_revenue(df, limit=20):
    """Return top products ranked by revenue."""

    products = (
        df.groupby(
            ["Product ID", "Product Name"],
            as_index=False
        )
        .agg(
            Units=("Quantity", "sum"),
            Orders=("Order ID", "nunique"),
            Revenue=("Revenue", "sum"),
            Profit=("Profit", "sum"),
        )
        .sort_values(
            "Revenue",
            ascending=False
        )
        .head(limit)
        .reset_index(drop=True)
    )

    products.insert(
        0,
        "Rank",
        range(
            1,
            len(products) + 1
        )
    )

    return products


