# ==========================================================
# CATEGORY ANALYSIS
# ==========================================================

def product_category_summary(df):
    """Return product performance by category."""

    return (
        df.groupby(
            "Category",
            as_index=False
        )
        .agg(
            Products=("Product ID", "nunique"),
            Units=("Quantity", "sum"),
            Orders=("Order ID", "nunique"),
            Revenue=("Revenue", "sum"),
            Profit=("Profit", "sum"),
        )
        .sort_values(
            "Revenue",
            ascending=False
        )
        .reset_index(drop=True)
    )


