# ==========================================================
# PRODUCT PROFITABILITY
# ==========================================================

def product_profitability(df, limit=20):
    """Return products ranked by profit margin."""

    summary = (
        df.groupby(
            ["Product ID", "Product Name"],
            as_index=False
        )
        .agg(
            Revenue=("Revenue", "sum"),
            Profit=("Profit", "sum"),
            Units=("Quantity", "sum"),
        )
    )

    summary["Profit Margin"] = (
        summary["Profit"]
        / summary["Revenue"]
        * 100
    )

    summary = (
        summary[
            summary["Revenue"] > 0
        ]
        .sort_values(
            "Profit Margin",
            ascending=False
        )
        .head(limit)
        .reset_index(drop=True)
    )

    summary.insert(
        0,
        "Rank",
        range(
            1,
            len(summary) + 1
        )
    )

    return summary


# ==========================================================
# PRODUCT DRILL-DOWN
# ==========================================================

def product_drilldown(df, product_name):
    """Return detailed performance for a selected product."""

    product_df = df[
        df["Product Name"] == product_name
    ].copy()

    if product_df.empty:
        return None

    revenue = product_df["Revenue"].sum()

    profit = product_df["Profit"].sum()

    units = product_df["Quantity"].sum()

    orders = product_df["Order ID"].nunique()

    customers = product_df["Customer ID"].nunique()

    regions = product_df["Region"].nunique()

    margin = (
        profit / revenue * 100
        if revenue != 0
        else 0
    )

    return {
        "Revenue": revenue,
        "Profit": profit,
        "Units": units,
        "Orders": orders,
        "Customers": customers,
        "Regions": regions,
        "Margin": margin,
    }


# ==========================================================
# PRODUCT RANKING
# ==========================================================

def product_ranking(df):
    """Return all products ranked by revenue."""

    ranking = (
        df.groupby(
            ["Product ID", "Product Name"],
            as_index=False
        )
        .agg(
            Units=("Quantity", "sum"),
            Orders=("Order ID", "nunique"),
            Customers=("Customer ID", "nunique"),
            Revenue=("Revenue", "sum"),
            Profit=("Profit", "sum"),
        )
        .sort_values(
            "Revenue",
            ascending=False
        )
        .reset_index(drop=True)
    )

    ranking.insert(
        0,
        "Rank",
        range(
            1,
            len(ranking) + 1
        )
    )

    ranking["Profit Margin"] = (
        ranking["Profit"]
        / ranking["Revenue"]
        * 100
    )

    return ranking

